type Queue struct {
    items []Event
    head  int
}

func (q *Queue) Post(e Event) { q.items = append(q.items, e) }

func (q *Queue) Drain(handle func(Event)) {
    for ; q.head < len(q.items); q.head++ {
        handle(q.items[q.head])
    }
    q.items = q.items[:0]
    q.head = 0
}
